import assert from "node:assert/strict";
import { readFile,writeFile,rename,unlink } from "node:fs/promises";
import { resolve } from "node:path";
const root=process.env.HALIEUS_DATA_DIR;
const {readPlayerProgression}=await import("../../server/src/platform/progression.ts");
let peak=process.memoryUsage().heapUsed;
const monitor=setInterval(()=>{peak=Math.max(peak,process.memoryUsage().heapUsed)},5);monitor.unref();
const first=await readPlayerProgression("one");
peak=Math.max(peak,process.memoryUsage().heapUsed);
assert.equal(first.played,192); assert.equal(first.wins,192);
assert.ok(first.awards.some(a=>a.id==="mega:comeback-victory"));
assert.ok(peak<96*1024*1024,"Archive statistics exceeded the 96 MiB heap budget: "+Math.round(peak/1024/1024)+" MiB");
const {readFinalisedSessionSummaries}=await import("../../server/src/platform/finalisedSessionSummaries.ts");
const final=resolve(root,"sessions/finalized");
const snapshots=await Promise.all(Array.from({length:12},()=>readFinalisedSessionSummaries([final],{strict:true})));
assert.equal(snapshots[0].length,192);
assert.ok(JSON.stringify(snapshots[0]).length<1024*1024,"Statistics retained replay payloads");
const both=await Promise.all([readPlayerProgression("one"),readPlayerProgression("two")]);
assert.equal(both[1].played,192); assert.equal(both[1].wins,0);
const file=resolve(final,"000.json"),saved=JSON.parse(await readFile(file,"utf8"));
saved.state.gameState.winnerPlayerId="p2";saved.state.gameState.players[0].isBankrupt=true;saved.state.gameState.players[1].isBankrupt=false;
await writeFile(file+".tmp",JSON.stringify(saved)); await rename(file+".tmp",file);
assert.equal((await readPlayerProgression("one")).wins,191,"Replaced archives must invalidate summaries");
await unlink(resolve(final,"001.json"));
assert.equal((await readPlayerProgression("one")).played,191,"Deleted archives must leave the index");
const broken=resolve(final,"002.json"),original=await readFile(broken,"utf8"); await writeFile(broken,"{broken");
await assert.rejects(readFinalisedSessionSummaries([final],{strict:true}));
assert.equal((await readFinalisedSessionSummaries([final])).length,190);
assert.equal((await readPlayerProgression("one")).played,191,"Archive failure must retain verified progression");
await writeFile(broken,original);
assert.equal((await readPlayerProgression("one")).played,191);
peak=Math.max(peak,process.memoryUsage().heapUsed);clearInterval(monitor);
assert.ok(peak<96*1024*1024,"Concurrent/replaced archive reads exceeded the heap budget");
console.log(JSON.stringify({passed:true,archiveCount:192,sourceBytes:192*700000,peakHeapMiB:Math.round(peak/1024/1024),concurrentReaders:12}));
